trait ShapeClone { fn clone_box(&self) -> Box<dyn Shape>; }
impl<T: 'static + Shape + Clone> ShapeClone for T {   // blanket impl once
    fn clone_box(&self) -> Box<dyn Shape> { Box::new(self.clone()) }
}
trait Shape: ShapeClone { fn area(&self) -> f64; }    // object-safe: no Self return
impl Clone for Box<dyn Shape> {
    fn clone(&self) -> Self { self.clone_box() }
}
